<?php
namespace Azula\SmsStudio;

/** SMS-owned, event-date reports. No GA4/Meta/provider calls or order/customer mutation. */
final class M6Analytics
{
    public function __construct(private M6Store $s,private ?AudienceSource $source){}
    public static function range(array $p):array
    {
        $zone=new \DateTimeZone(CairoTime::ZONE);$today=new \DateTimeImmutable('today',$zone);$preset=$p['range']??'30';$start=$today->modify('-29 days');$end=$today;
        if($preset==='today')$start=$today;elseif($preset==='yesterday')$start=$end=$today->modify('-1 day');elseif($preset==='7')$start=$today->modify('-6 days');elseif($preset==='custom'){
            foreach(['from','to'] as $key){$raw=$p[$key]??'';if(!is_string($raw)||!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$raw))throw new ControlledTestException('Enter valid Egypt report dates.');$date=\DateTimeImmutable::createFromFormat('!Y-m-d',$raw,$zone);if(!$date||$date->format('Y-m-d')!==$raw)throw new ControlledTestException('Invalid Egypt report date.');if($key==='from')$start=$date;else $end=$date;}
        }elseif($preset!=='30')throw new ControlledTestException('Unsupported report range.');
        if($end<$start||$start->diff($end)->days>365)throw new ControlledTestException('Use an ordered report range of at most 366 Egypt dates.');
        return ['from'=>$start->format('Y-m-d'),'to'=>$end->format('Y-m-d'),'start_utc'=>$start->getTimestamp(),'end_utc'=>$end->modify('+1 day')->setTime(0,0)->getTimestamp(),'timezone'=>CairoTime::ZONE];
    }
    private function filter(array $p):string
    {
        $db=$this->s->database->db;$filter=M8Tokens::modern()?"1=1":"COALESCE(m.purpose,'campaign')='campaign'";foreach(['campaign'=>'id','segment'=>'segment_id'] as $key=>$column){$raw=$p[$key]??'';if($raw===''||$raw==='0')continue;if(!is_string($raw)||!preg_match('/^[1-9][0-9]{0,9}$/D',$raw))throw new ControlledTestException('Invalid report scope.');$filter.=$db->prepare(' AND c.'.$column.'=%d',(int)$raw);}if(M8Tokens::modern())$filter.=" AND EXISTS (SELECT id FROM ".$this->s->table('attempts')." sent_attempt WHERE sent_attempt.campaign_id=c.id AND sent_attempt.state IN ('accepted','rejected','unknown'))";return $filter;
    }
    private function points(int $start,int $end,string $filter,?int $campaign=null):array
    {
        $a=$this->s->table('attempts');$c=$this->s->table('campaigns');$m=$this->s->table('campaign_meta');$extra=$campaign===null?'':' AND c.id='.(int)$campaign;if(M8Tokens::modern())$extra.=" AND a.state IN ('accepted','rejected','unknown')";
        $rows=$this->s->rows("SELECT a.id,a.cost,a.receipt,a.state,a.provider_code,a.smsid FROM $a a INNER JOIN $c c ON c.id=a.campaign_id LEFT JOIN $m m ON m.campaign_id=c.id WHERE $filter$extra AND a.claimed_at>=%d AND a.claimed_at<%d ORDER BY a.id ASC LIMIT 10001",$start,$end);$value='0';$missing=0;if(M8Tokens::modern())return (new M8Costs($this->s))->total($rows);if(count($rows)>10000)return ['reported'=>null,'missing'=>null,'reason'=>'Cost exceeds the bounded report limit; no partial total is presented.'];foreach($rows as $r){if($r['cost']===null)$missing++;else $value=ExactPoints::add($value,(string)$r['cost']);}return ['reported'=>$value,'missing'=>$missing,'reason'=>'Provider units, not verified monetary expenditure. Missing Cost values are not assumed zero.'];
    }
    public function report(array $p,bool $export=false):array
    {
        $range=self::range($p);$from=$range['start_utc'];$to=$range['end_utc'];$filter=$this->filter($p);$campaigns=$this->s->table('campaigns');$meta=$this->s->table('campaign_meta');$attempts=$this->s->table('attempts');$clicks=$this->s->table('clicks');$journey=$this->s->table('journey');$conversions=$this->s->table('conversions');$raw=$this->s->table('link_requests');$page=max(1,(int)($p['page']??1));$direction=($p['direction']??'desc')==='asc'?'ASC':'DESC';
        $joins=" FROM $campaigns c LEFT JOIN $meta m ON m.campaign_id=c.id
LEFT JOIN (SELECT campaign_id,COUNT(*) requests,SUM(CASE WHEN state IN ('accepted','rejected') THEN recipient_count ELSE 0 END) submitted,SUM(CASE WHEN state='accepted' THEN recipient_count ELSE 0 END) accepted,SUM(CASE WHEN state='rejected' THEN recipient_count ELSE 0 END) rejected,SUM(CASE WHEN state='unknown' THEN recipient_count ELSE 0 END) unknown_count,MIN(CASE WHEN state='accepted' THEN claimed_at END) first_accepted,SUM(CAST(cost AS DECIMAL(65,18))) cost_sort FROM $attempts WHERE claimed_at>=$from AND claimed_at<$to GROUP BY campaign_id) a ON a.campaign_id=c.id
LEFT JOIN (SELECT campaign_id,SUM(CASE WHEN request_recorded=0 THEN 1 ELSE 0 END) link_requests,COUNT(DISTINCT CASE WHEN observed_at>0 AND recipient_link_id>0 THEN recipient_link_id END) recipient_links_accessed,COUNT(DISTINCT CASE WHEN observed_at>0 THEN visitor_hash END) unique_clicks,SUM(CASE WHEN observed_at>0 THEN 1 ELSE 0 END) visits FROM $clicks WHERE clicked_at>=$from AND clicked_at<$to GROUP BY campaign_id) k ON k.campaign_id=c.id
LEFT JOIN (SELECT campaign_id,SUM(hits) raw_requests FROM $raw WHERE bucket>=$from AND bucket<$to GROUP BY campaign_id) q ON q.campaign_id=c.id
LEFT JOIN (SELECT campaign_id,SUM(CASE WHEN kind='product_view' THEN 1 ELSE 0 END) product_views,SUM(CASE WHEN kind='add_to_cart' THEN 1 ELSE 0 END) carts,SUM(CASE WHEN kind='checkout_start' THEN 1 ELSE 0 END) checkouts FROM $journey WHERE occurred_at>=$from AND occurred_at<$to GROUP BY campaign_id) j ON j.campaign_id=c.id
LEFT JOIN (SELECT campaign_id,COUNT(*) associated_orders,SUM(purchase_eligible) purchases,SUM(revenue_minor) revenue,SUM(CASE WHEN verified_at=0 OR reason IN ('analytics_contract_unavailable','order_unavailable','invalid_or_ambiguous_amount','currency_not_egp') THEN 1 ELSE 0 END) finance_pending,MIN(verified_at) last_finance FROM $conversions WHERE order_created>=$from AND order_created<$to GROUP BY campaign_id) v ON v.campaign_id=c.id
WHERE $filter AND ((c.created_at>=$from AND c.created_at<$to) OR a.requests>0 OR k.link_requests>0 OR q.raw_requests>0 OR j.carts>0 OR j.checkouts>0 OR j.product_views>0 OR v.associated_orders>0)";
        $totals=$this->s->row('SELECT COUNT(*) campaigns,COALESCE(SUM(a.requests),0) requests,COALESCE(SUM(a.submitted),0) submitted,COALESCE(SUM(a.accepted),0) accepted,COALESCE(SUM(a.rejected),0) rejected,COALESCE(SUM(a.unknown_count),0) unknown_count,COALESCE(SUM(k.unique_clicks),0) unique_clicks,COALESCE(SUM(k.link_requests),0)+COALESCE(SUM(q.raw_requests),0) link_requests,COALESCE(SUM(k.recipient_links_accessed),0) recipient_links_accessed,COALESCE(SUM(k.visits),0) visits,COALESCE(SUM(j.product_views),0) product_views,COALESCE(SUM(j.carts),0) carts,COALESCE(SUM(j.checkouts),0) checkouts,COALESCE(SUM(v.purchases),0) purchases,COALESCE(SUM(v.revenue),0) revenue_minor,COALESCE(SUM(v.finance_pending),0) finance_pending,MIN(v.last_finance) last_finance'.$joins);
        $revenueOverflow=false;foreach($totals as $key=>$value){if(M8Tokens::modern()&&$key==='revenue_minor'&&(strlen((string)$value)>strlen((string)PHP_INT_MAX)||(strlen((string)$value)===strlen((string)PHP_INT_MAX)&&strcmp((string)$value,(string)PHP_INT_MAX)>0))){$revenueOverflow=true;$totals[$key]=null;}else $totals[$key]=$value===null?null:(int)$value;}if($revenueOverflow)$totals['finance_pending']++;$totals['provider_cost']=$this->points($from,$to,$filter);$totals['monetary_cost_egp']=null;$totals['roi']=null;$totals['roas']=null;
        $columns=['name'=>'c.name','accepted'=>'accepted','clicks'=>'unique_clicks','purchases'=>'purchases','revenue'=>'revenue_minor','cost'=>'a.cost_sort','sent'=>'a.first_accepted','conversion'=>'conversion_rate'];$sort=$columns[$p['sort']??'sent']??'a.first_accepted';$limit=$export?10001:26;$offset=$export?0:($page-1)*25;
        $rows=$this->s->rows('SELECT c.id,c.name,c.segment_id,c.created_at,a.first_accepted,COALESCE(a.accepted,0) accepted,COALESCE(a.rejected,0) rejected,COALESCE(a.unknown_count,0) unknown_count,COALESCE(k.unique_clicks,0) unique_clicks,COALESCE(k.link_requests,0)+COALESCE(q.raw_requests,0) link_requests,COALESCE(k.recipient_links_accessed,0) recipient_links_accessed,COALESCE(v.purchases,0) purchases,COALESCE(v.revenue,0) revenue_minor,CASE WHEN a.accepted>0 THEN COALESCE(v.purchases,0)*100.0/a.accepted ELSE NULL END conversion_rate'.$joins." ORDER BY $sort $direction,c.id DESC LIMIT $limit OFFSET $offset");if($export&&count($rows)>10000)throw new \LengthException('Campaign export exceeds 10,000 rows. Narrow the report range or scope.');$more=!$export&&count($rows)>25;if(!$export)$rows=array_slice($rows,0,25);
        foreach($rows as &$row){$row['id']=(int)$row['id'];$row['segment_id']=(int)$row['segment_id'];try{$row['segment']=$this->source->segment($row['segment_id'])['name'];}catch(\Throwable $e){$row['segment']='Saved segment #'.$row['segment_id'].' (source unavailable)';}$row['sending_egypt']=$row['first_accepted']?CairoTime::label((int)$row['first_accepted']):null;$row['provider_cost']=$this->points($from,$to,$filter,$row['id']);$row['roi']=null;$row['roas']=null;}unset($row);
        $orders=[];if(!empty($p['campaign'])){$orders=$this->s->rows("SELECT order_id,order_created,status,currency,revenue_minor,purchase_eligible,reason,verified_at FROM $conversions WHERE campaign_id=%d AND order_created>=%d AND order_created<%d ORDER BY order_created DESC,order_id DESC LIMIT 26 OFFSET %d",(int)$p['campaign'],$from,$to,(max(1,(int)($p['order_page']??1))-1)*25);}
        $orderMore=count($orders)>25;$orders=array_slice($orders,0,25);
        $out=['range'=>$range,'totals'=>$totals,'rows'=>$rows,'page'=>$page,'more'=>$more,'orders'=>$orders,'orders_more'=>$orderMore,'coverage'=>['raw_retention_days'=>30,'collection_status'=>M7Settings::modern()?M7Settings::status():null,'collection_enabled'=>M6Tracking::enabled(),'attribution_contract'=>M6AttributionContracts::available(),'finance_contract'=>M6AttributionContracts::exclusions()!==null,'last_finance_verified'=>$totals['last_finance'],'finance_pending'=>$totals['finance_pending'],'human_identity'=>'Unavailable. Unique clicks are observed anonymous browser/campaign pairs, not verified people.','visits'=>'Browser or Woo-observed click receipts; scanner/HEAD/prefetch requests are not counted as observed visits.','revenue'=>'Eligible EGP order-cohort gross remaining after refunds, as of reconciliation. Not cash collected or Analytics net sales.','attribution'=>'Snapshot-constrained last SMS campaign, fixed seven-day click window. No multi-touch or Meta attribution claim.','monetary_roi'=>'Unavailable: provider Cost has no verified EGP basis.']];
        if(M8Tokens::modern())$out=(new M8Analytics($this->s))->decorate($out,$filter);return $out;
    }
}
